import logging
from lxml import etree
from ipaddress import ip_address
from builtins import str
from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.collector import CommonOamCollector, VduCollector, CommonOamCUCollector
from abc import abstractmethod
import time
from taf.internal.managedobject import Using

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class L2StreamCollectorBase(Using("local_executor"), StartableCollector):  # type: ignore[misc]
    def __init__(self,
                 destination_ip_addr,
                 collector,
                 dscp=0,
                 destination_port_number=5678,
                 **kwargs):
        super(L2StreamCollectorBase, self).__init__(**kwargs)
        self._destination_ip_addr = destination_ip_addr
        self._destination_port_number = destination_port_number
        self._dscp = dscp
        self._collector = collector
        self.add_prerequisite(self._collector)

    def _start(self):
        self._collector.start()

    def _stop(self):
        self._collector.stop()

    def _collect(self, target_dir):
        self._collector.collect(target_dir)

    def _get_rd_component_bit_map_values(self, profile_filter_list, event_filter_list):  # noqa: C901
        rd_bit_map_dict = {}
        if profile_filter_list is not None:
            profile_filter_list = [profile for profile in profile_filter_list if profile != 'Use RnD parameters']
            if len(profile_filter_list) != 0:
                profile_bit_number_list = self._get_profile_numbers(profile_filter_list)
                profile_value = sum(2 ** bit_number for bit_number in profile_bit_number_list)
                rd_bit_map_dict['rdComponentBitMapProfile'] = profile_value
            else:
                rd_bit_map_dict['rdComponentBitMapProfile'] = 0
        hex_to_string_mapping = {
            '0x580900': 'rdComponentBitMapVector0',
            '0x580901': 'rdComponentBitMapVector1',
            '0x580902': 'rdComponentBitMapVector2',
            '0x580903': 'rdComponentBitMapVector3',
            '0x580904': 'rdComponentBitMapVector4',
            '0x580905': 'rdComponentBitMapVector5'
        }
        if event_filter_list:
            event_list = " ".join(event_filter_list)
            command = f"""source {self._tti_dec_path}/venv/bin/activate && cd {self._tti_dec_path}/tti-dec-bin && """ \
                      f"""python scripts/eventToRnd.py -n {event_list}"""
            stdout = self._local_executor.execute(command.encode('utf-8'))
            vector_values = stdout.decode('utf-8').strip().splitlines()[1:]
            for line in vector_values:
                value = line.split()
                rd_bit_map_dict[hex_to_string_mapping.get(value[0].strip())] = value[1].strip()
        elif event_filter_list == []:
            for key in hex_to_string_mapping.values():
                rd_bit_map_dict[key] = '0x0'
        return rd_bit_map_dict

    @abstractmethod
    def _enable_l2_streaming_on_gnb(self):
        pass

    @abstractmethod
    def _disable_l2_streaming_on_gnb(self):
        pass


class SbtsL2StreamCollector(CommonOamCollector,
                            L2StreamCollectorBase):
    """
              To Start , Stop and Collect L2stream logs on given configuration using cOAM admin cli.
    """

    def __init__(self,
                 l2_stream_configuration,
                 start_timeout=None,
                 stop_timeout=None,
                 source_ip_addr=None,
                 tti_dec_path="/opt/tti-dec",
                 **kwargs):
        super(SbtsL2StreamCollector, self).__init__(**kwargs)
        self._generate_pci_celldn_dict = False
        self._source_ip_addr = source_ip_addr
        self._start_kwargs = {}
        self._stop_kwargs = {}
        self._l2_stream_configuration = []
        self._tti_dec_path = tti_dec_path
        for parameter_dictionary in l2_stream_configuration:
            self._l2_stream_configuration.append(self._verify_l2_stream_parameters(parameter_dictionary))
        if len(self._l2_stream_configuration) == 0:
            raise RuntimeError("Argument l2_stream_configuration is not in proper format")
        if start_timeout:
            self._start_kwargs['timeout'] = start_timeout
        if stop_timeout:
            self._stop_kwargs['timeout'] = stop_timeout

    def _verify_l2_stream_parameters(self, parameter_dictionary):
        if any(parameter in parameter_dictionary for parameter in ("eq_id", "pci_list", "node_id")):
            raise RuntimeError("eq_id/pci_list/node_id is not allowed for cOAM admin cli")
        l2stream_parameters = {
            'up_sw': parameter_dictionary.get("up_sw", "L2Ps"),
            'trace_type': parameter_dictionary.get("trace_type", "Component")}
        if "nr_phy_cell_ids" in parameter_dictionary.keys():
            l2stream_parameters["nr_phy_cell_ids"] = parameter_dictionary["nr_phy_cell_ids"]
            self._generate_pci_celldn_dict = True
        else:
            l2stream_parameters["nr_cell_dns"] = parameter_dictionary.get("nr_cell_dns", [])
        if (l2stream_parameters['up_sw'].lower() == 'l2ps'
                and l2stream_parameters['trace_type'].lower() == 'component'):
            if 'profile_filter_list' in parameter_dictionary:
                l2stream_parameters['profile_filter_list'] = parameter_dictionary["profile_filter_list"]
            if 'event_filter_list' in parameter_dictionary:
                l2stream_parameters['event_filter_list'] = parameter_dictionary["event_filter_list"]
        return l2stream_parameters

    def _update_rad_parameters(self, rd_component_bit_map_values):
        self._managed_admin_connection.set_multiple_rad_debug_parameters(
            domain='L2PS',
            persistency='NotPersistent',
            rad_parameters=[{'name': param, 'value': str(value)} for param, value in
                            rd_component_bit_map_values.items()])

    def _get_profile_numbers(self, profile_filter_list):
        response = self._managed_admin_connection.get_rad_debug_parameter_details(
            domain='L2PS', parameter_name='rdComponentBitMapProfile')
        profile_numbers = [bitmask['bitNumber'] for bitmask in response['bitmaskValues'] if
                           bitmask['meaning'] in profile_filter_list]
        return profile_numbers

    def _enable_l2_streaming_on_gnb(self):
        for parameter_dictionary in self._l2_stream_configuration:
            if "nr_phy_cell_ids" in parameter_dictionary.keys():
                parameter_dictionary["nr_cell_dns"] = [
                    self.phycellid_celldns_dict[id] for id in parameter_dictionary["nr_phy_cell_ids"]]
                parameter_dictionary.pop("nr_phy_cell_ids")
            profile_filter_list = parameter_dictionary.get('profile_filter_list')
            event_filter_list = parameter_dictionary.pop('event_filter_list', None)
            rd_component_bit_map_values = self._get_rd_component_bit_map_values(profile_filter_list, event_filter_list)
            if rd_component_bit_map_values:
                self._update_rad_parameters(rd_component_bit_map_values)
            if profile_filter_list or event_filter_list:
                parameter_dictionary['profile_filter_list'] = ['Use RnD parameters']
            logger.debug("Calling start_uplane_l2_trace for "
                         f"source_ip={self._source_ip_addr}, dscp={self._dscp}, "
                         f"destination_ip={self._destination_ip_addr}, "
                         f"destination_port={self._destination_port_number}, "
                         f"additional_parameters={parameter_dictionary}, "
                         f"start_kwargs={self._start_kwargs}")
            self._managed_admin_connection.start_uplane_l2_trace(
                source_ip=self._source_ip_addr,
                dscp=self._dscp,
                destination_ip=self._destination_ip_addr,
                destination_port=self._destination_port_number,
                **parameter_dictionary,
                **self._start_kwargs)

    def _disable_l2_streaming_on_gnb(self):
        for parameter_dictionary in self._l2_stream_configuration:
            try:
                self._managed_admin_connection.stop_uplane_l2_trace(
                    trace_type=parameter_dictionary["trace_type"],
                    up_sw=parameter_dictionary["up_sw"],
                    **self._stop_kwargs)
            except Exception as e:
                logger.debug('Avoiding disable_l2_streaming error: {}'.format(e))

    def _setup(self):
        if self._generate_pci_celldn_dict:
            bts_info = self._managed_admin_connection.get_bts_info()
            nr_cells = bts_info["cells"]["nr"]
            phycellid_to_dn_mapping = {}
            for nr_cell in nr_cells:
                pci = nr_cell["physicalCellId"]
                dn = nr_cell["id"]["internal"]
                if pci in phycellid_to_dn_mapping:
                    raise ValueError(
                        f"Duplicate physCellId {pci} found: "
                        f"'{phycellid_to_dn_mapping[pci]}' and '{dn}'. "
                        f"In this case, cells have to be identified in a different way than via physCellId.")
                phycellid_to_dn_mapping[pci] = dn
            self.phycellid_celldns_dict = phycellid_to_dn_mapping
        if not self._source_ip_addr:
            source_ip_xpath = "//*[@class='com.nokia.srbts.tnl:IPADDRESSV{version}']/*[@name='localIpAddr']".format(
                version=ip_address(str(self._destination_ip_addr)).version)
            self._source_ip_addr = etree.fromstring(
                getattr(self._managed_admin_connection, 'get_scf',
                        getattr(self._managed_admin_connection, 'get_current_scf_content', None))().encode(
                    "utf-8")).xpath(source_ip_xpath)[0].text
        self._disable_l2_streaming_on_gnb()
        self._enable_l2_streaming_on_gnb()

    def _teardown(self):
        self._disable_l2_streaming_on_gnb()


class CuVduL2StreamCollectorBase(L2StreamCollectorBase):
    """
    To Start , Stop and Collect L2stream logs on given configuration.
    """

    def __init__(self,
                 timeout=15,
                 **kwargs):
        super(CuVduL2StreamCollectorBase, self).__init__(**kwargs)
        self._timeout = timeout

    def _setup(self):
        self._update_uplane_configuration()
        self._disable_l2_streaming_on_gnb()
        self._enable_l2_streaming_on_gnb()

    def _teardown(self):
        self._disable_l2_streaming_on_gnb()

    def _update_uplane_configuration(self):
        logger.debug(
            "update_uplane_configuration: "
            "destination_ip_addr={_destination_ip_addr!r}, "
            "destination_port_number={_destination_port_number!r}, "
            "dscp={_dscp!r}".format(**self.__dict__))
        self._operation_id = self._do_update_uplane_configuration()
        self._wait_until_status(
            get_result=self._get_trs_operation_status,
            check_result=lambda result, target_status: result == target_status,
            target_status='Successful')

    def _get_trace_stream_statuses(self):
        start_time = time.time()
        while True:
            statuses = {
                (trace_stream.target_component, trace_stream.trace_type): trace_stream.status
                for trace_stream in self._managed_connection.get_active_trace_streams()
                if (trace_stream.target_component, trace_stream.trace_type) in self._trace_stream_types}
            if set(statuses) == set(self._trace_stream_types):
                break
            if time.time() - start_time > self._timeout:
                raise RuntimeError(
                    "could not fetch the current statuses of "
                    "all started trace stream types {trace_stream_types!r} "
                    "within {timeout} seconds: at least one trace status is unknown : {statuses!r}".format(
                        statuses=statuses,
                        trace_stream_types=self._trace_stream_types,
                        timeout=self._timeout))
            time.sleep(0.1)
        if "Failed" in statuses.values():
            raise RuntimeError(
                "for trace stream types {trace_stream_types!r} "
                "at least one trace status is 'Failed' : {statuses!r}".format(
                    statuses=statuses,
                    trace_stream_types=self._trace_stream_types))
        return list(statuses.values())

    def _wait_until_status(self, get_result, check_result, target_status):
        last_result = None
        start_time = time.time()
        while True:
            if time.time() - start_time > self._timeout:
                raise RuntimeError(
                    "target status {target_status!r} not reached "
                    "within {timeout} seconds: {last_result!r}".format(
                        target_status=target_status,
                        timeout=self._timeout,
                        last_result=last_result))
            result = get_result()
            if result != last_result:
                last_result = result
                logger.debug("{}".format(result))
            if check_result(result, target_status):
                break
            time.sleep(0.1)

    def _disable_l2_streaming_on_gnb(self):
        trace_ids = [
            trace_stream.trace_id
            for trace_stream in self._managed_connection.get_active_trace_streams()
            if (trace_stream.target_component, trace_stream.trace_type) in self._trace_stream_types]
        for trace_id in trace_ids:
            try:
                logger.debug("Calling stop_uplane_trace_stream for trace_id {}".format(trace_id))
                self._managed_connection.stop_uplane_trace_stream(trace_id=trace_id)
                self._wait_until_status(
                    get_result=self._get_trace_stream_statuses,
                    check_result=lambda result, target_status: all(
                        status == target_status for status in result),
                    target_status='Stopped')
            except Exception as e:
                logger.debug('Avoiding disable_l2_streaming error: {}'.format(e))


class VduL2StreamCollector(VduCollector, CuVduL2StreamCollectorBase):
    """
    To Start , Stop and Collect L2stream logs on given configuration using managed vDU connection.
    """
    _parameter_mapping = {'nr_cell_dns': 'nr_cell_dn_list', 'up_sw': 'target_component'}

    def __init__(self,
                 l2_stream_configuration,
                 tti_dec_path="/opt/tti-dec",
                 **kwargs):
        super(VduL2StreamCollector, self).__init__(**kwargs)
        self._tti_dec_path = tti_dec_path
        self._l2_stream_configuration = []
        self._trace_stream_types = []
        self._generate_name_dns_dict = False
        self._managed_connection = self._managed_vdu_connection
        for parameter_dictionary in l2_stream_configuration:
            parameter_dictionary = {self._parameter_mapping.get(k, k): v for k, v in parameter_dictionary.items()}
            if any(key not in parameter_dictionary for key in ('trace_type', 'target_component')) or \
                    all(key not in parameter_dictionary for key in ('nr_cell_dn_list', 'nr_cell_name_list')):
                raise RuntimeError("trace_type/target_component/(nr_cell_dn_list or nr_cell_name_list) are"
                                   " mandatory parameters for vDU start trace api")
            if 'nr_cell_name_list' in parameter_dictionary:
                self._generate_name_dns_dict = True
            if not (parameter_dictionary['target_component'].lower() == 'l2ps'
                    and parameter_dictionary['trace_type'].lower() == 'component'):
                parameter_dictionary.pop("profile_filter_list", None)
                parameter_dictionary.pop("event_filter_list", None)
            self._l2_stream_configuration.append(parameter_dictionary)
            self._trace_stream_types.append(
                (
                    parameter_dictionary["target_component"],
                    parameter_dictionary["trace_type"]))

    def _do_update_uplane_configuration(self):
        return self._managed_vdu_connection.update_uplane_configuration(
            uplane_ip_addr=self._destination_ip_addr,
            uplane_port=self._destination_port_number,
            dscp=self._dscp)

    def _setup(self):
        if self._generate_name_dns_dict:
            self._update_l2_stream_configuration_with_dn_list()
        super(VduL2StreamCollector, self)._setup()

    def _update_l2_stream_configuration_with_dn_list(self):
        name_dns_dict = {
            cell_status['name']: cell_status['dist_names']['config']
            for cell_status in self._managed_vdu_connection.get_vdu_cells_status()}
        logger.debug('generated name_dns_dict: {}'.format(name_dns_dict))
        for parameter_dictionary in self._l2_stream_configuration:
            if 'nr_cell_name_list' in parameter_dictionary:
                parameter_dictionary['nr_cell_dn_list'] = [
                    name_dns_dict[name]
                    for name in parameter_dictionary['nr_cell_name_list']]

    def _get_trs_operation_status(self):
        api_operation_status = self._managed_vdu_connection.get_trs_api_operation_status(
            operation_id=self._operation_id).status
        logger.debug("api operation status {}".format(api_operation_status))
        if api_operation_status == 'Failed':
            raise RuntimeError("api operation status might have been failed, Please check")
        return api_operation_status

    def _update_rad_parameters(self, rd_component_bit_map_values):
        api_status = self._managed_connection.update_rad_debug_params(
            persistency='notPersistent',
            domain_name='L2PS',
            parameters=[{'name': param, 'value': str(value)} for param, value in rd_component_bit_map_values.items()])
        self._rad_operation_id = api_status.operation_id
        self._wait_until_status(
            get_result=self._get_rad_debug_params_update_status,
            check_result=lambda result, target_status: result == target_status,
            target_status='succeeded')

    def _get_rad_debug_params_update_status(self):
        result = self._managed_connection.get_rad_debug_params_update_operation(operation_id=self._rad_operation_id)
        logger.debug("update_rad_debug_params status {}".format(result.status))
        if result.status == 'Failed':
            raise RuntimeError("update_rad_debug_params failed")
        return result.status

    def _get_profile_numbers(self, profile_filter_list):
        response = self._managed_connection.rad_reload_params(domain_name='L2PS')
        while True:
            response = self._managed_connection.get_reload_params_operation(
                operation_id=response.operation_id).to_dict()
            if response['status'] != "ongoing":
                break
        l2ps_params = [x['parameters'] for x in response['rad_params']][0]
        bitmask_values = [x['bitmask_values'] for x in l2ps_params if x['name'] == "rdComponentBitMapProfile"][0]
        profile_numbers = [i for i, bitmask_value in enumerate(bitmask_values[:-1]) if
                           bitmask_value['text'] in profile_filter_list]
        return profile_numbers

    def _enable_l2_streaming_on_gnb(self):
        for parameter_dictionary in self._l2_stream_configuration:
            profile_filter_list = parameter_dictionary.get('profile_filter_list')
            event_filter_list = parameter_dictionary.pop('event_filter_list', None)
            rd_component_bit_map_values = self._get_rd_component_bit_map_values(profile_filter_list, event_filter_list)
            if rd_component_bit_map_values:
                self._update_rad_parameters(rd_component_bit_map_values)
            logger.debug("Calling start_uplane_trace_stream for"
                         " trace_type {trace_type}"
                         " target_component {target_component}"
                         " nr_cell_dn_list {nr_cell_dn_list}".format(**parameter_dictionary))
            self._managed_vdu_connection.start_uplane_trace_stream(
                trace_type=parameter_dictionary['trace_type'],
                target_component=parameter_dictionary['target_component'],
                nr_cell_dn_list=parameter_dictionary['nr_cell_dn_list'])
        self._wait_until_status(
            get_result=self._get_trace_stream_statuses,
            check_result=lambda result, target_status: all(
                status == target_status for status in result),
            target_status='Active')


class CoamCUL2StreamCollector(CommonOamCUCollector, CuVduL2StreamCollectorBase):
    """
    To Start , Stop and Collect L2stream logs on given configuration using managed Coam CU connection.
    """
    _parameter_mapping = {'up_sw': 'target_component'}

    def __init__(self,
                 l2_stream_configuration,
                 **kwargs):
        super(CoamCUL2StreamCollector, self).__init__(**kwargs)
        self._l2_stream_configuration = []
        self._trace_stream_types = []
        for parameter_dictionary in l2_stream_configuration:
            parameter_dictionary = {self._parameter_mapping.get(k, k): v for k, v in parameter_dictionary.items()}
            if any(key not in parameter_dictionary for key in ('trace_type', 'target_component')):
                raise RuntimeError("trace_type/target_component are"
                                   " mandatory parameters for CU start trace api")
            self._l2_stream_configuration.append(parameter_dictionary)
            self._trace_stream_types.append(
                (
                    parameter_dictionary["target_component"],
                    parameter_dictionary["trace_type"]))

        self._managed_connection = self._cu_connection

    def _do_update_uplane_configuration(self):
        return self._cu_connection.update_uplane_configuration(
            ip_address=self._destination_ip_addr,
            port=self._destination_port_number,
            dscp=self._dscp)

    def _enable_l2_streaming_on_gnb(self):
        for parameter_dictionary in self._l2_stream_configuration:
            logger.debug("Calling start_uplane_trace_stream for"
                         " trace_type {trace_type}"
                         " target_component {target_component}".format(**parameter_dictionary))
            self._cu_connection.start_uplane_trace_stream(
                trace_type=parameter_dictionary['trace_type'],
                target_component=parameter_dictionary['target_component'])
        self._wait_until_status(
            get_result=self._get_trace_stream_statuses,
            check_result=lambda result, target_status: all(
                status == target_status for status in result),
            target_status='Active')

    def _get_trs_operation_status(self):
        trs_operation_status = self._cu_connection.get_trs_operation_status(
            operation_id=self._operation_id).status
        logger.debug("api operation status {}".format(trs_operation_status))
        if trs_operation_status == 'Failed':
            raise RuntimeError("trs operation status might have been failed, Please check")
        return trs_operation_status
